    "A unique request identifier is required.": "एक अद्वितीय अनुरोध पहचानकर्ता आवश्यक है।",
    "A verified authentication subject is required.": "एक सत्यापित प्रमाणीकरण विषय आवश्यक है।",
    "APP_MODE must be production or development.": "APP_MODE उत्पादन या विकास होना चाहिए।",
    "Account contract and signing operator": "खाता अनुबंध और साइनिंग ऑपरेटर",
    "Account status could not be verified.": "खाता स्थिति की जाँच नहीं की जा सकी।",
    "Account transactions are unavailable while Worldo completes its NEAR setup.": "जब तक Worldo NEAR सेटअप पूरा नहीं कर लेता, खाता लेनदेन उपलब्ध नहीं है।",
    "All four chain businesses must be registered.": "चारों श्रृंखला व्यवसायों को पंजीकृत करना आवश्यक है।",
    "Allow the NEAR sign-in popup, then try again.": "NEAR साइन-इन पॉपअप की अनुमति दें, फिर फिर से प्रयास करें।",
    "An oracle command needs operator review before this world can continue.": "एक ओरेकल कमांड को इस दुनिया के आगे बढ़ने से पहले ऑपरेटर द्वारा समीक्षा की आवश्यकता है।",
    "Approve the current action first.": "पहले वर्तमान क्रिया को स्वीकार करें।",
    "Auth callback is not available.": "प्राथमिकता कॉलबैक उपलब्ध नहीं है।",
    "Authorization does not match the current action. Please approve it again.": "प्राधिकरण वर्तमान क्रिया से मेल नहीं खाता। कृपया इसे फिर से स्वीकार करें।",
    "Balanced stock · steady demand": "संतुलित स्टॉक · स्थिर मांग",
    "Borrowed a survey scanner from the depot.": "डिपो से एक सर्वेक्षण स्कैनर उधार लिया।",
    "Bought": "खरीदा",
    "Bought a survey scanner. Search North ridge for an oil deposit.": "सर्वेक्षण स्कैनर खरीदा गया। उत्तरी रिज पर तेल का भंडार खोजें।",
    "Bring a can of petrol or park beside a fuel seller.": "पेट्रोल की एक कैन लाएं या ईंधन विक्रेता के बगल में पार्क करें।",
    "Browser test wallets are available only on NEAR testnet.": "ब्राउज़र परीक्षण वॉलेट NEAR टेस्टनेट पर ही उपलब्ध हैं।",
    "Build your refinery · consumes 10 steel and 10 planks": "अपनी रिफाइनरी बनाएं · 10 स्टील और 10 प्लैंक्स का उपयोग करता है",
    "Building needs 10 steel and 10 planks.": "निर्माण के लिए 10 स्टील और 10 प्लैंक्स की आवश्यकता होती है।",
    "Building needs 4 steel beams and 6 bundles of planks.": "इमारत को 4 स्टील बीम और 6 बंडल प्लैंक्स की आवश्यकता है।",
    "Buy": "खरीदें",
